import os
import subprocess
import zipfile
import re

source_dir = '/root/papers/all/'
target_base = '/root/papers/'
categories = {
    'LLM': ['llm', 'large language model', 'transformer', 'nlp', 'gpt', 'bert', 'token', 'pre-training', 'rlhf', 'instruction tuning', 'language model'],
    'trapped_ion_and_qc': ['trapped ion', 'quantum computing', 'quantum computer', 'qubit', 'superconducting', 'entanglement', 'quantum gate', 'rydberg', 'quantum circuit', 'ion trap'],
    'black_hole': ['black hole', 'event horizon', 'schwarzschild', 'hawking', 'general relativity', 'gravitational wave', 'einstein', 'spacetime', 'accretion', 'kerr metric'],
    'DNA': ['dna', 'rna', 'genome', 'genomic', 'sequencing', 'nucleotide', 'chromosome', 'gene', 'protein', 'mutation', 'biological', 'nucleic acid', 'polynucleotide'],
    'music_history': ['music', 'composer', 'renaissance', 'baroque', 'classical period', 'romantic period', 'orchestra', 'symphony', 'opera', 'sonata', 'polyphony', 'beethoven', 'bach', 'mozart', 'history of music']
}

def get_pdf_text(filepath):
    try:
        # Extract first 3 pages to be safe
        result = subprocess.run(['pdftotext', '-l', '3', filepath, '-'], capture_output=True, text=True)
        return result.stdout.lower()
    except Exception as e:
        print(f"Error reading PDF {filepath}: {e}")
        return ""

def get_docx_text(filepath):
    try:
        with zipfile.ZipFile(filepath, 'r') as zip_ref:
            xml_content = zip_ref.read('word/document.xml').decode('utf-8')
            # Very simple tag stripping
            text = re.sub('<[^>]+>', ' ', xml_content)
            return text.lower()
    except Exception as e:
        print(f"Error reading DOCX {filepath}: {e}")
        return ""

def get_pptx_text(filepath):
    try:
        text_parts = []
        with zipfile.ZipFile(filepath, 'r') as zip_ref:
            # Look at first few slides
            for i in range(1, 10):
                slide_path = f'ppt/slides/slide{i}.xml'
                if slide_path in zip_ref.namelist():
                    xml_content = zip_ref.read(slide_path).decode('utf-8')
                    text_parts.append(re.sub('<[^>]+>', ' ', xml_content))
        return " ".join(text_parts).lower()
    except Exception as e:
        print(f"Error reading PPTX {filepath}: {e}")
        return ""

def categorize(text, filename):
    # Combine filename and text for better matching
    full_search = (filename + " " + text).lower()

    # Use a scoring system
    scores = {cat: 0 for cat in categories}
    for cat, keywords in categories.items():
        for kw in keywords:
            if kw in full_search:
                # Give more weight to specific keywords or multiple occurrences
                scores[cat] += full_search.count(kw)

    best_cat = max(scores, key=scores.get)
    if scores[best_cat] == 0:
        # Default to the last one as per instruction "if a file does not fit into any other 4 folders, it should fit into the last one"
        # The 5th subject is music_history
        return 'music_history'
    return best_cat

files = os.listdir(source_dir)
for f in files:
    path = os.path.join(source_dir, f)
    if not os.path.isfile(path):
        continue

    text = ""
    if f.endswith('.pdf'):
        text = get_pdf_text(path)
    elif f.endswith('.docx'):
        text = get_docx_text(path)
    elif f.endswith('.pptx'):
        text = get_pptx_text(path)

    cat = categorize(text, f)
    dest = os.path.join(target_base, cat, f)

    print(f"Moving {f} to {cat}")
    os.rename(path, dest)

print("Done!")

